<?php if ($view === 'reservations'): ?>
<form class="catalog-filters" method="get" action="/admin/reservas"><div><label for="reserve-filter-event">Evento (nombre)</label><input id="reserve-filter-event" name="event" maxlength="80" value="<?= $escape($filter->event) ?>"></div><div><label for="reserve-filter-user">Usuario (nombre o correo)</label><input id="reserve-filter-user" name="user" maxlength="80" value="<?= $escape($filter->user) ?>"></div><div><label for="reserve-filter-state">Estado de reserva</label><select id="reserve-filter-state" name="state"><?php foreach (['' => 'Todas', 'CONFIRMADA' => 'Confirmada', 'CANCELADA' => 'Cancelada'] as $state => $label): ?><option value="<?= $state ?>" <?= $filter->state === $state ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div><button class="button" type="submit">Filtrar reservas</button><a href="/admin/reservas">Limpiar filtros</a></form>
<?php if ($rows === []): ?><p class="notice">No encontramos reservas con estos filtros.</p><?php endif; ?>
<div class="event-grid admin-list"><?php foreach ($rows as $item): ?><article class="event-card"><h2><?= $escape($item['event_name']) ?></h2><p><?= $escape($item['full_name']) ?></p><p><?= $escape($item['email']) ?></p><p><?= (int) $item['quantity'] ?> entradas · <?= Eventify\Support\Format::money($item['total']) ?></p><p>Reserva <?= $escape($item['status']) ?> · Evento <?= $escape($item['display_event_status']) ?></p><p>Creada <?= $date($item['created_at']) ?> (Costa Rica)</p><a href="/admin/reservas/<?= (int) $item['id'] ?>">Consultar reserva</a></article><?php endforeach; ?></div>
<?php $reservePage = static fn (int $page): string => '/admin/reservas?' . http_build_query(['event' => $filter->event, 'user' => $filter->user, 'state' => $filter->state, 'page' => $page]); ?>
<nav class="catalog-pagination" aria-label="Páginas de reservas"><?php if ($filter->page > 1): ?><a href="<?= $escape($reservePage($filter->page - 1)) ?>">Anterior</a><?php endif; ?><span>Página <?= $filter->page ?></span><?php if ($hasMore): ?><a href="<?= $escape($reservePage($filter->page + 1)) ?>">Siguiente</a><?php endif; ?></nav>
<?php else: ?>
<article class="admin-form-card reservation-detail"><h2><?= $escape($record['event_name']) ?></h2><p>Información conservada de la reserva. Esta consulta no permite modificarla.</p><dl><dt>Identificador de reserva</dt><dd><?= $escape($record['code']) ?></dd><dt>Usuario</dt><dd><?= $escape($record['full_name']) ?> · <?= $escape($record['email']) ?></dd><dt>Fecha del evento</dt><dd><?= $date($record['starts_at']) ?> (Costa Rica)</dd><dt>Ubicación</dt><dd><?= $escape($record['location']) ?></dd><dt>Cantidad</dt><dd><?= (int) $record['quantity'] ?> entradas</dd><dt>Precio histórico por entrada</dt><dd><?= Eventify\Support\Format::money($record['unit_price']) ?></dd><dt>Total histórico</dt><dd><?= Eventify\Support\Format::money($record['total']) ?></dd><dt>Estado de reserva</dt><dd><?= $escape($record['status']) ?></dd><dt>Estado del evento</dt><dd><?= $escape($record['display_event_status']) ?></dd><dt>Creada</dt><dd><?= $date($record['created_at']) ?> (Costa Rica)</dd><?php if ($record['cancelled_at'] !== null): ?><dt>Cancelada</dt><dd><?= $date($record['cancelled_at']) ?> (Costa Rica)</dd><?php endif; ?><dt>Identificador del ticket</dt><dd><?= $escape($record['ticket_code']) ?></dd></dl><a class="return-link" href="/admin/reservas">Volver a reservas</a></article>
<?php endif; ?>
